#!/usr/bin/env swift
//
//  generate-icons.swift
//  The single source of truth for every raster app icon / favicon.
//
//  Run from anywhere:
//      swift scripts/generate-icons.swift
//
//  It renders the Unpeel mark as a frosted-glass panel over the hero twilight
//  sky (the same `hero-garden.webp` used on the landing page), edges faded
//  inward, and writes every PNG target below. Add a new size/destination to
//  `targets` and re-run — don't hand-edit the PNGs.
//
//  Uses only AppKit (NSImage decodes the SVG + webp exactly like the native app
//  does), so there are no external dependencies.
//

import AppKit

// MARK: - Source artwork

// The mark: two-panel "peel" artwork. We keep the raw path data (not a
// rasterised SVG) so the glass treatment can light and shade the real edges.
// `dFront` is the lower/solid panel, `dBack` the upper/faint one. H/V commands
// are normalized to absolute L so the minimal parser below can read it.
//
// LOGO:START — generated by scripts/update-logo.mjs from scripts/logo-source.svg
let markSize: CGFloat = 446
let dFront = "M408.833 446C429.36 446 446 429.36 446 408.833L446 223C446 212.737 437.68 204.417 427.417 204.417L364.233 204.417C353.97 204.417 345.65 212.737 345.65 223L345.65 327.067C345.65 337.33 337.33 345.65 327.067 345.65L118.933 345.65C108.67 345.65 100.35 337.33 100.35 327.067L100.35 223C100.35 212.737 92.03 204.417 81.7667 204.417L18.5833 204.417C8.32004 204.417 0 212.737 0 223L0 408.833C0 429.36 16.6401 446 37.1667 446L408.833 446Z"
let dBack = "M1.62461e-05 37.1667C1.80406e-05 16.6401 16.6401 -1.19583e-06 37.1667 0L408.833 3.24921e-05C429.36 3.42866e-05 446 16.6401 446 37.1667L446 223L345.65 223L345.65 118.933C345.65 108.67 337.33 100.35 327.067 100.35L118.933 100.35C108.67 100.35 100.35 108.67 100.35 118.933L100.35 223L0 223L1.62461e-05 37.1667Z"
// LOGO:END

// MARK: - Minimal SVG path parser (absolute M/L/C/Z — all this artwork uses)

func tokenize(_ d: String) -> [(Character, [CGFloat])] {
    var out: [(Character, [CGFloat])] = []
    let ch = Array(d); let n = ch.count; var i = 0
    var cmd: Character? = nil; var nums: [CGFloat] = []
    func flush() { if let c = cmd { out.append((c, nums)); nums = [] } }
    while i < n {
        let c = ch[i]
        if c.isLetter { flush(); cmd = c; i += 1 }
        else if c == " " || c == "," || c == "\n" || c == "\t" { i += 1 }
        else {
            var j = i
            if ch[j] == "-" || ch[j] == "+" { j += 1 }
            while j < n {
                let d2 = ch[j]
                if d2.isNumber || d2 == "." { j += 1 }
                else if d2 == "e" || d2 == "E" { j += 1; if j < n && (ch[j] == "-" || ch[j] == "+") { j += 1 } }
                else { break }
            }
            if let v = Double(String(ch[i..<j])) { nums.append(CGFloat(v)) }
            i = j
        }
    }
    flush(); return out
}

func buildPath(_ d: String) -> CGPath {
    let p = CGMutablePath()
    for (cmd, a) in tokenize(d) {
        switch cmd {
        case "M":
            p.move(to: CGPoint(x: a[0], y: a[1]))
            var k = 2; while k + 1 < a.count { p.addLine(to: CGPoint(x: a[k], y: a[k+1])); k += 2 }
        case "L":
            var k = 0; while k + 1 < a.count { p.addLine(to: CGPoint(x: a[k], y: a[k+1])); k += 2 }
        case "C":
            var k = 0; while k + 5 < a.count {
                p.addCurve(to: CGPoint(x: a[k+4], y: a[k+5]),
                           control1: CGPoint(x: a[k], y: a[k+1]),
                           control2: CGPoint(x: a[k+2], y: a[k+3])); k += 6 }
        case "Z", "z": p.closeSubpath()
        default: break
        }
    }
    return p
}

// MARK: - Tunables

let aspect: CGFloat = 1.0                  // mark height / width (square artwork)
let markFraction: CGFloat = 0.52          // mark width relative to the icon body
let cornerFraction: CGFloat = 0.2237      // Apple-ish squircle radius

// Hero sky framing — "B": square crop biased low so the warm horizon glow sits
// under the mark; edges faded inward so the scene melts into the squircle.
let cropYBias: CGFloat = 0.78
let edgeFade: CGFloat = 0.32
let bottomLift: CGFloat = 0.14
// Uniform dark wash over the sky so the solid-white "U" reads brighter (higher
// contrast against a deeper twilight). 0 = raw sky, 1 = black.
let skyDarken: CGFloat = 0.42

// Logo: the lower "U" panel is solid white (no fade) so it stays crisp in the
// Dock; the upper, peeled-back panel is drawn fainter (see the 0.55 overall
// below) so it reads as translucent glass being lifted off. Glass character
// now comes from the lit rim + the faded upper panel rather than a frosted
// fill, so the mark never looks washed out.
let gFrost: CGFloat = 1.0        // fully opaque white fill
let gSheenTop: CGFloat = 0.40    // top sheen alpha
let gSideShade: CGFloat = 0.0    // no side darkening — keep the U uniformly bright
let gRimTop: CGFloat = 0.90      // bright top rim
let gRimBottom: CGFloat = 0.40   // dim bottom rim
let gLeftHi: CGFloat = 0.0       // no directional wash on the solid fill

func hex(_ v: Int, _ a: CGFloat = 1) -> NSColor {
    NSColor(srgbRed: CGFloat((v >> 16) & 0xFF) / 255,
            green: CGFloat((v >> 8) & 0xFF) / 255,
            blue: CGFloat(v & 0xFF) / 255, alpha: a)
}
let space = CGColorSpaceCreateDeviceRGB()
func grad(_ stops: [(NSColor, CGFloat)]) -> CGGradient {
    CGGradient(colorsSpace: space, colors: stops.map { $0.0.cgColor } as CFArray,
               locations: stops.map { $0.1 })!
}

// MARK: - Load assets

let repoRoot = URL(fileURLWithPath: #filePath)
    .deletingLastPathComponent()   // scripts/
    .deletingLastPathComponent()   // repo root

let heroURL = repoRoot.appendingPathComponent("apps/website/public/hero-garden.webp")
guard let hero = NSImage(contentsOf: heroURL),
      let heroCG = hero.cgImage(forProposedRect: nil, context: nil, hints: nil) else {
    FileHandle.standardError.write(Data("failed to load hero sky at \(heroURL.path)\n".utf8))
    exit(1)
}

// MARK: - Glass logo panel

func drawGlassPanel(_ ctx: CGContext, path: CGPath, body: NSRect, overall: CGFloat) {
    let b = path.boundingBox
    let rimW = max(1.2, body.width * 0.006)
    ctx.saveGState()
    ctx.addPath(path); ctx.clip()
    hex(0xFFFFFF, gFrost * overall).setFill(); b.fill()
    // vertical sheen, top bright → bottom faint
    ctx.drawLinearGradient(grad([(hex(0xFFFFFF, gSheenTop * overall), 0), (hex(0xFFFFFF, 0), 1)]),
        start: CGPoint(x: b.midX, y: b.maxY), end: CGPoint(x: b.midX, y: b.minY), options: [])
    // side shades — darken near the left & right edges (the glassy bevel)
    ctx.drawLinearGradient(grad([(hex(0x0C0A14, gSideShade * overall), 0),
                                 (hex(0x0C0A14, 0), 0.30),
                                 (hex(0x0C0A14, 0), 0.70),
                                 (hex(0x0C0A14, gSideShade * overall), 1)]),
        start: CGPoint(x: b.minX, y: b.midY), end: CGPoint(x: b.maxX, y: b.midY), options: [])
    // directional left highlight
    if gLeftHi > 0 {
        ctx.drawLinearGradient(grad([(hex(0xFFFFFF, gLeftHi * overall), 0), (hex(0xFFFFFF, 0), 0.22)]),
            start: CGPoint(x: b.minX, y: b.midY), end: CGPoint(x: b.maxX, y: b.midY), options: [])
    }
    ctx.restoreGState()
    // rim light — stroke the true edge with a top→bottom gradient
    let stroked = path.copy(strokingWithWidth: rimW, lineCap: .round, lineJoin: .round, miterLimit: 10)
    ctx.saveGState()
    ctx.addPath(stroked); ctx.clip()
    ctx.drawLinearGradient(grad([(hex(0xFFFFFF, gRimTop * overall), 0), (hex(0xFFFFFF, gRimBottom * overall), 1)]),
        start: CGPoint(x: b.midX, y: b.maxY), end: CGPoint(x: b.midX, y: b.minY), options: [])
    ctx.restoreGState()
}

// MARK: - Rendering

/// `pad` is the transparent margin around the rounded square, as a fraction of
/// the canvas. `square` draws an opaque, un-rounded full-bleed tile (corners
/// included) instead of a self-rounded squircle: macOS 26 (Tahoe) applies its
/// own rounded-rect mask to the Dock tile and only fills the slot edge-to-edge
/// for icons whose art reaches the corners — a pre-rounded squircle is treated
/// as "legacy" and drawn inset/smaller. The web favicon + extension icons keep
/// `square: false` (they're shown as-is, no system mask).
func render(size px: Int, pad: CGFloat, square: Bool = false) -> Data? {
    guard let rep = NSBitmapImageRep(
        bitmapDataPlanes: nil, pixelsWide: px, pixelsHigh: px,
        bitsPerSample: 8, samplesPerPixel: 4, hasAlpha: true, isPlanar: false,
        colorSpaceName: .calibratedRGB, bytesPerRow: 0, bitsPerPixel: 0
    ) else { return nil }
    rep.size = NSSize(width: px, height: px)

    NSGraphicsContext.saveGraphicsState()
    NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: rep)
    defer { NSGraphicsContext.restoreGraphicsState() }
    let ctx = NSGraphicsContext.current!.cgContext

    let f = CGFloat(px)
    let body = NSRect(x: 0, y: 0, width: f, height: f).insetBy(dx: f * pad, dy: f * pad)
    let radius = body.width * cornerFraction
    if square {
        NSBezierPath(rect: body).addClip()
    } else {
        NSBezierPath(roundedRect: body, xRadius: radius, yRadius: radius).addClip()
    }

    // base fill so any transparency reads dark
    hex(0x141118).setFill(); body.fill()

    // 1. Hero sky — square crop biased low, aspect-filled into the body.
    let iw = CGFloat(heroCG.width), ih = CGFloat(heroCG.height)
    let side = min(iw, ih)
    let crop = heroCG.cropping(to: CGRect(
        x: (iw - side) / 2, y: (ih - side) * cropYBias, width: side, height: side))!
    ctx.saveGState(); ctx.interpolationQuality = .high; ctx.draw(crop, in: body); ctx.restoreGState()

    // 2. Edge fade — radial vignette pulling dark in from the sides/corners.
    let c = CGPoint(x: body.midX, y: body.midY)
    ctx.drawRadialGradient(grad([(hex(0x000000, 0), 0), (hex(0x000000, 0), 0.55), (hex(0x0C0A12, edgeFade), 1)]),
        startCenter: c, startRadius: 0, endCenter: c, endRadius: body.width * 0.72,
        options: [.drawsAfterEndLocation])
    NSGradient(colors: [hex(0x0C0A12, bottomLift), hex(0x0C0A12, 0)])?
        .draw(in: NSRect(x: body.minX, y: body.minY, width: body.width, height: body.height * 0.45), angle: 90)

    // 2b. Uniform dark wash — deepens the sky so the white mark pops brighter.
    hex(0x0A0712, skyDarken).setFill(); body.fill()

    // 3. The mark, as frosted glass. Map the artwork's own coordinate space
    //    (markSize × markSize) into a centered, optically-sized rect (CG y-up,
    //    so flip the vertical axis).
    let markW = body.width * markFraction, markH = markW * aspect
    let markRect = NSRect(x: body.midX - markW / 2, y: body.midY - markH / 2, width: markW, height: markH)
    var t = CGAffineTransform(translationX: markRect.minX, y: markRect.maxY)
        .scaledBy(x: markRect.width / markSize, y: -markRect.height / markSize)
    let front = buildPath(dFront).copy(using: &t)!
    let back = buildPath(dBack).copy(using: &t)!

    // 3a. Soft drop-shadow halo behind the whole mark for separation from the sky.
    ctx.saveGState()
    ctx.setShadow(offset: CGSize(width: 0, height: -body.width * 0.006),
                  blur: body.width * 0.022, color: hex(0x000000, 0.5).cgColor)
    ctx.setFillColor(hex(0x000000, 1).cgColor)
    ctx.addPath(front); ctx.addPath(back); ctx.fillPath()
    ctx.restoreGState()
    // 3b. Restore the interior to sky so the translucent glass sits over the
    //     scene, not the black shadow fill (which now reads only as an outer halo).
    ctx.saveGState()
    ctx.addPath(front); ctx.addPath(back); ctx.clip()
    ctx.interpolationQuality = .high; ctx.draw(crop, in: body)
    ctx.restoreGState()
    // 3c. Glass panels — faint upper panel first, full lower panel on top.
    drawGlassPanel(ctx, path: back, body: body, overall: 0.55)
    drawGlassPanel(ctx, path: front, body: body, overall: 1.0)

    // 4. Outer squircle rim — hairline highlight along the edge. Skipped in
    //    `square` mode: the system mask rounds (and crops) the corners, so a
    //    full-bleed edge rim would just be clipped off.
    if !square {
        let inset = max(1, body.width * 0.004)
        let rim = NSBezierPath(roundedRect: body.insetBy(dx: inset, dy: inset),
                               xRadius: radius - inset, yRadius: radius - inset)
        rim.lineWidth = inset; hex(0xFFFFFF, 0.12).setStroke(); rim.stroke()
    }

    return rep.representation(using: .png, properties: [:])
}

// MARK: - Targets (all paths relative to the repo root)

struct Target { let path: String; let size: Int; var pad: CGFloat = 0; var square: Bool = false }
let targets: [Target] = [
    // Web app icon — also the browser favicon (src/renderer.tsx). Self-rounded
    // squircle (shown as-is in the browser, no system mask).
    Target(path: "apps/website/public/app-icon.png", size: 512),
    // Native macOS app icon — full-bleed *square*. On macOS 26 (Tahoe) the Dock
    // applies its own rounded-rect mask and only fills the slot edge-to-edge for
    // icons whose art reaches the corners; a self-rounded squircle is treated as
    // legacy and drawn inset/smaller than its neighbours. square: true draws an
    // opaque tile to the corners so the system mask fills the whole slot.
    Target(path: "apps/native/UnpeelNative/Sources/UnpeelNative/Resources/AppIcon.png", size: 1024, pad: 0, square: true),
]

for t in targets {
    guard let png = render(size: t.size, pad: t.pad, square: t.square) else {
        FileHandle.standardError.write(Data("render failed: \(t.path)\n".utf8))
        exit(1)
    }
    let url = repoRoot.appendingPathComponent(t.path)
    do {
        try png.write(to: url)
        print("wrote \(t.path) (\(t.size)px)")
    } catch {
        FileHandle.standardError.write(Data("write failed \(t.path): \(error)\n".utf8))
        exit(1)
    }
}
print("done — \(targets.count) icons")
